/* ---------- abierto / cerrado (lunes a sábados 9:00 a 23:00 hs) ---------- */
const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
function ahoraBA() {
  const p = Object.fromEntries(new Intl.DateTimeFormat('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
    .formatToParts(new Date()).map(x => [x.type, x.value]));
  return { dia: p.weekday, dd: +p.day, mm: +p.month, yy: +p.year, h: +p.hour, m: +p.minute };
}
function pintarEstado() {
  const t = ahoraBA(), abierto = t.dia !== 'domingo' && t.h >= 9 && t.h < 23;
  $$('.estado').forEach(e => {
    e.classList.toggle('cerrado', !abierto);
    e.querySelector('span').textContent = abierto ? 'Abierto · cierra 23:00 hs' : (t.dia === 'sábado' && t.h >= 23) || t.dia === 'domingo' ? 'Cerrado · abre el lunes 9:00 hs' : 'Cerrado · abre a las 9:00 hs';
  });
  const f = $('.pizarra__fecha');
  if (f) f.textContent = `HOY · ${t.dia.toUpperCase()} ${String(t.dd).padStart(2, '0')}/${String(t.mm).padStart(2, '0')}`;
  const tb = $('[data-horas]');
  if (tb && !tb.dataset.ok) {
    tb.dataset.ok = 1;
    tb.innerHTML = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'].map(d =>
      `<tr${d === t.dia ? ' class="hoy-dia"' : ''}><td>${d[0].toUpperCase() + d.slice(1)}</td><td>${d === 'domingo' ? 'Cerrado' : '9:00 a 23:00 hs'}</td></tr>`).join('');
  }
  // cuenta regresiva al 29
  const n = $('[data-cuenta-n]');
  if (n) {
    const hoy = new Date(t.yy, t.mm - 1, t.dd);
    let obj = new Date(t.yy, t.mm - 1, 29);
    if (t.dd > 29 || obj.getMonth() !== t.mm - 1) obj = new Date(t.yy, t.mm, 29);
    if (obj.getDate() !== 29) obj = new Date(t.yy, t.mm + 1, 29); // febrero
    const dif = Math.round((obj - hoy) / 864e5);
    n.textContent = dif === 0 ? '¡Hoy!' : dif;
    $('[data-cuenta-t]').innerHTML = dif === 0 ? 'es 29:<br>hay ñoquis' : dif === 1 ? 'día para<br>el 29' : 'días para<br>el 29';
  }
}

/* ---------- pizarra: letras sueltas, un poco torcidas ---------- */
function pizarra(el, txt) {
  if (!el) return;
  let i = 0;
  el.setAttribute('aria-label', txt);
  el.innerHTML = '';
  txt.split(' ').forEach((w, k, arr) => {
    const pal = document.createElement('span'); pal.className = 'palabra'; pal.setAttribute('aria-hidden', 'true');
    for (const ch of w) {
      const s = document.createElement('span'); s.className = 'letra'; s.textContent = ch; s.style.setProperty('--i', i++);
      s.style.setProperty('--r', ((Math.random() - .5) * 3.4).toFixed(1) + 'deg');
      s.style.setProperty('--y', ((Math.random() - .5) * 4).toFixed(1) + 'px');
      pal.append(s);
    }
    el.append(pal); if (k < arr.length - 1) el.append(' ');
  });
}

/* ---------- intro: el logo gira en su eje y aterriza en la marca del hero ---------- */
function intro() {
  const html = document.documentElement, ov = $('.intro');
  const fin = () => { html.classList.remove('con-intro'); html.classList.add('listo'); ov?.remove(); };
  if (!html.classList.contains('con-intro') || !ov) return fin();
  const celu = innerWidth < 700, celu0 = celu, t0 = performance.now();
  const hero = $('[data-hero-img]');
  const espera = Promise.race([
    Promise.all([document.fonts.ready, hero && !hero.complete ? new Promise(r => { hero.onload = hero.onerror = r; }) : 0]),
    new Promise(r => setTimeout(r, celu0 ? 1300 : 2200)),
  ]);
  espera.then(() => {
    const falta = Math.max(0, (celu ? 1000 : 1150) - (performance.now() - t0));
    setTimeout(() => {
      const de = $('.intro__logo').getBoundingClientRect(), a = $('.marca').getBoundingClientRect();
      const logo = $('.intro__logo');
      const dx = a.left + a.width / 2 - (de.left + de.width / 2), dy = a.top + a.height / 2 - (de.top + de.height / 2), sc = a.width / de.width;
      ov.classList.add('sale');
      $('.marca').style.opacity = 0;
      logo.animate([{ transform: 'none' }, { transform: `translate(${dx}px,${dy}px) scale(${sc})` }], { duration: celu ? 480 : 560, easing: 'cubic-bezier(.6,0,.2,1)', fill: 'forwards' })
        .finished.then(() => { $('.marca').style.opacity = ''; fin(); });
      setTimeout(() => html.classList.add('listo'), 120);
    }, falta);
  });
}


/* ---------- el spiedo ---------- */
function spiedo(raiz) {
  if (!raiz) return;
  const N = SPIEDO.length, cuerpo = $('.sp-cuerpo', raiz);
  const items = SPIEDO.map((x, i) => {
    const el = document.createElement('div'); el.className = 'sp-item';
    el.innerHTML = `<i class="sp-brazo"></i><i class="sp-gancho"></i>
      <button class="sp-plato" type="button" aria-label="${x.n}, ${pesos(x.p)}"><img src="img/${x.id}-240.webp" srcset="img/${x.id}-240.webp 240w, img/${x.id}-480.webp 480w" sizes="200px" alt="" width="240" height="240" decoding="async"${raiz.hasAttribute('data-lazy') ? ' loading="lazy"' : ''} draggable="false"><i class="brillo"></i><i class="sombra"></i></button>`;
    cuerpo.append(el);
    const tier = i % 2;
    return { x, el, base: Math.floor(i / 2) * 90 + tier * 45, tier, brazo: $('.sp-brazo', el), gancho: $('.sp-gancho', el), plato: $('.sp-plato', el), sombra: $('.sombra', el), brillo: $('.brillo', el) };
  });
  const wrap = raiz.closest('.sp-wrap') || raiz;
  const vapor = $('.sp-vapor', raiz);
  const band = $('.sp-bandera', raiz), pop = $('.sp-pop', raiz), info = $('.sp-ctrl p', wrap);
  let rot = 0, vel = 0, auto = true, arrastre = null, objetivo = null, frente = -1, ult = performance.now(), quieto = 0;

  function dibujar() {
    const W = raiz.clientWidth, H = raiz.clientHeight, cx = W / 2, R = W * .36, P = R * 3.2, D = W * .3;
    let mejor = -1, mz = -1e9;
    items.forEach((it, i) => {
      const th = (it.base + rot) * Math.PI / 180, x = R * Math.sin(th), z = R * Math.cos(th);
      const s = P / (P - z) * .82, ty = H * (it.tier ? .62 : .27) + z * .1;
      const px = cx + x * s, d = D * s, gancho = d * .32;
      it.el.style.zIndex = Math.round(50 + z / R * 40);
      it.brazo.style.left = cx + 'px'; it.brazo.style.top = (ty - 2) + 'px';
      it.brazo.style.width = Math.max(4, Math.hypot(px - cx, 0)) + 'px';
      it.brazo.style.transform = `scaleX(${px < cx ? -1 : 1})`;
      it.gancho.style.left = (px - 1.5) + 'px'; it.gancho.style.top = ty + 'px'; it.gancho.style.height = gancho + 'px';
      it.plato.style.width = it.plato.style.height = d + 'px';
      it.plato.style.transform = `translate(${px - d / 2}px,${ty + gancho - d * .06}px)`;
      it.sombra.style.opacity = (.62 - (z + R) / (2 * R) * .62).toFixed(2);
      it.brillo.style.setProperty('--lx', (50 - x / R * 38).toFixed(0) + '%');
      it.px = px; it.py = ty + gancho; it.d = d;
      if (z > mz) { mz = z; mejor = i; }
    });
    const it = items[mejor], ang = ((it.base + rot) % 360 + 540) % 360 - 180, cerca = Math.abs(ang) < 14;
    if (mejor !== frente) {
      frente = mejor;
      band.classList.toggle('hoy', !!it.x.hoy);
      $('b', band).textContent = it.x.n; $('span', band).textContent = (it.x.desde ? 'desde ' : '') + pesos(it.x.p) + (it.x.unidad ? ' c/u' : '');
      info.textContent = `Girá el spiedo · ${mejor + 1}/${N}`;
    }
    band.classList.toggle('ver', cerca && !pop.classList.contains('abierto'));
    if (vapor) { vapor.style.transform = `translate(${it.px - 45}px,${it.py - 100}px)`; vapor.style.zIndex = 94; }
    const bw = band.offsetWidth;
    band.style.transform = `translate(${Math.min(W - bw, it.px + it.d * .18)}px,${it.py + it.d * .5 - 44}px)`;
  }

  function paso(t) {
    const dt = Math.min(48, t - ult) / 1000; ult = t;
    if (!arrastre) {
      if (objetivo !== null) {
        const dif = objetivo - rot; rot += dif * Math.min(1, dt * 7);
        if (Math.abs(dif) < .05) { rot = objetivo; objetivo = null; }
      } else if (Math.abs(vel) > 4) { rot += vel * dt; vel *= Math.pow(.05, dt); }
      else if (vel !== 0) { vel = 0; encajar(); }
      else if (auto && !pop.classList.contains('abierto')) rot -= 9 * dt;
      else { quieto += dt; if (quieto > 7 && !pop.classList.contains('abierto')) { auto = true; } }
    }
    dibujar(); requestAnimationFrame(paso);
  }
  function encajar(idx) {
    if (idx === undefined) { const k = Math.round((rot) / 45); objetivo = k * 45; return; }
    let o = -items[idx].base; o += Math.round((rot - o) / 360) * 360; objetivo = o;
  }
  const girarA = idx => { auto = false; quieto = 0; vel = 0; encajar(idx); };
  // arrastre con dedo o mouse
  let mov = 0;
  raiz.addEventListener('pointerdown', e => {
    if (e.target.closest('.sp-pop,.sp-ctrl')) return;
    arrastre = { x: e.clientX, r: rot, t: performance.now(), lx: e.clientX }; mov = 0; auto = false; objetivo = null; vel = 0; quieto = 0;
    raiz.setPointerCapture(e.pointerId);
  });
  raiz.addEventListener('pointermove', e => {
    if (!arrastre) return;
    const dx = e.clientX - arrastre.x; mov = Math.max(mov, Math.abs(dx));
    rot = arrastre.r + dx * (300 / raiz.clientWidth);
    const now = performance.now(), dtt = now - arrastre.t;
    if (dtt > 0) vel = (e.clientX - arrastre.lx) * (300 / raiz.clientWidth) / dtt * 1000;
    arrastre.t = now; arrastre.lx = e.clientX;
  });
  const soltar = e => {
    if (!arrastre) return; arrastre = null;
    if (mov < 6) { // fue un toque
      vel = 0;
      const b = document.elementsFromPoint(e.clientX, e.clientY).find(n => n.classList?.contains('sp-plato'));
      const idx = b ? items.findIndex(it => it.plato === b) : -1;
      if (idx >= 0) { if (idx === frente) abrir(idx); else { girarA(idx); setTimeout(() => abrir(idx), 520); } }
      else encajar();
    } else if (Math.abs(vel) < 40) { vel = 0; encajar(); }
  };
  raiz.addEventListener('pointerup', soltar); raiz.addEventListener('pointercancel', soltar);
  // teclado / botones
  $('[data-sp="ant"]', wrap).onclick = () => girarA((frente + N - 1) % N);
  $('[data-sp="sig"]', wrap).onclick = () => girarA((frente + 1) % N);
  items.forEach((it, i) => it.plato.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); girarA(i); setTimeout(() => abrir(i), 450); } }));
  function abrir(i) {
    const x = items[i].x;
    $('img', pop).src = x.foto480; $('.sp-pop__cat', pop).textContent = x.cat;
    $('h3', pop).textContent = x.n; $('.sp-pop__desc', pop).textContent = x.d;
    $('.sp-pop__precio', pop).textContent = (x.desde ? 'desde ' : '') + pesos(x.p);
    pop.classList.add('abierto'); pop.setAttribute('aria-hidden', 'false'); pop.dataset.t = Date.now(); $('.sp-pop__x', pop).focus({ preventScroll: true });
  }
  raiz.irA = (id) => { const i = items.findIndex(it => it.x.id === id); if (i >= 0) girarA(i); };
  const cerrar = () => { pop.classList.remove('abierto'); pop.setAttribute('aria-hidden', 'true'); quieto = 0; };
  $('.sp-pop__x', pop).onclick = cerrar;
  document.addEventListener('keydown', e => { if (e.key === 'Escape') cerrar(); });
  document.addEventListener('pointerdown', e => { if (pop.classList.contains('abierto') && !e.target.closest('.sp-pop')) cerrar(); }, true);
  $('[data-sumar]', pop).onclick = () => { if (Date.now() - (+pop.dataset.t || 0) < 450) return; const x = items[frente].x; if (KIT?.carrito) KIT.carrito.agregar(x.id, 1); avisar(`Sumaste ${x.n}`); cerrar(); };
  raiz.refrescar = () => { frente = -1; };
  requestAnimationFrame(t => { ult = t; paso(t); });
}


/* ---------- el mostrador: familias con lo que más sale ---------- */
const FAMILIAS = [
  { cat: 'spiedo', foto: 'cuarto-muslo', ids: ['cuarto-muslo', 'cuarto-pechuga', 'medio-pollo', 'pollo-entero', 'pechuga-a-la-mostaza'] },
  { cat: 'milanesas', foto: 'mila-napo-ternera', ids: ['mila-ternera', 'mila-napo-ternera', 'mila-caballo', 'mila-fugazzeta-ternera', 'suprema-napo'] },
  { cat: 'pastas', foto: 'noquis-papa', ids: ['noquis-papa', 'ravioles', 'sorrentinos-calabaza', 'lasana', 'canelones-verdura'] },
  { cat: 'caseros', foto: 'pastel-papa', ids: ['pastel-papa', 'arroz-amarillo', 'bife-chorizo', 'tarta-pollo-verdeo', 'tortilla-cebolla'] },
  { cat: 'empanadas', foto: 'empapana-carne', ids: ['empapana-carne', 'empapana-pollo', 'empapana-jyq', 'empanada-criolla-carne', 'empanada-criolla-pollo-parmesano'] },
  { cat: 'sandwiches', foto: 'sandwich-mila-ternera-papas', ids: ['sandwich-mila-ternera-papas', 'sandwich-mila-ternera-completo', 'sandwich-mila-pollo-completo', 'ciabatta-mila-pollo-completo', 'ciabatta-jyq'] },
];
const corto = (n) => n.replace(/^Milanesa de /, 'Mila de ').replace(/^Sándwich de milanesa de /, 'Sándwich de mila de ').replace(/ al spiedo$/, '').replace(/ con papas fritas$/, '').replace(/^Ciabatta de milanesa de /, 'Ciabatta de mila de ');
function mostrador(cats, prods) {
  const track = $('[data-mostrador]'), chips = $('.fam-chips');
  if (!track) return;
  const P = new Map(prods.map(p => [p.id, p]));
  const C = new Map(cats.map(c => [c.id, c]));
  track.innerHTML = FAMILIAS.map((f, k) => {
    const c = C.get(f.cat); if (!c) return '';
    const total = prods.filter(p => p.categoria === f.cat).length;
    let lista = f.ids.map(id => P.get(id)).filter(Boolean);
    if (lista.length < 5) lista = lista.concat(prods.filter(p => p.categoria === f.cat && !lista.includes(p))).slice(0, 5);
    return `<article class="fam" id="fam-${f.cat}" data-k="${k}">
      <div class="fam__cab"><div class="fam__foto"><img src="img/${f.foto}-240.webp" alt="" width="64" height="64" loading="lazy" draggable="false"></div>
      <div><h3>${c.nombre}</h3><p class="fam__n">${total} opciones</p></div></div>
      <ul>${lista.map(p => `<li${p.disponible === false ? ' class="off"' : ''}><div class="fam__txt"><b>${corto(p.nombre)}</b><span>${pesos(p.precio)}</span></div>${p.disponible === false ? '<em>Hoy no</em>' : `<div data-kit-qty="${p.id}"></div>`}</li>`).join('')}</ul>
      <a class="fam__mas" href="carta/">Ver las ${total} →</a></article>`;
  }).join('');
  chips.innerHTML = FAMILIAS.map((f, k) => `<button type="button" class="fam-chip" aria-pressed="${k === 0}" data-k="${k}">${C.get(f.cat)?.nombre || ''}</button>`).join('');
  KIT?.carrito?.sync(track);
}
function mostradorInteraccion() {
  const track = $('[data-mostrador]'), chips = $('.fam-chips');
  chips.addEventListener('click', e => {
    const b = e.target.closest('.fam-chip'); if (!b) return;
    const card = track.querySelector(`.fam[data-k="${b.dataset.k}"]`);
    if (card) track.scrollTo({ left: card.offsetLeft - (track.clientWidth - card.offsetWidth) / 2, behavior: 'smooth' });
  });
  let raf = 0;
  track.addEventListener('scroll', () => {
    cancelAnimationFrame(raf);
    raf = requestAnimationFrame(() => {
      const mid = track.scrollLeft + track.clientWidth / 2; let k = 0, best = 1e9;
      $$('.fam', track).forEach(c => { const d = Math.abs(c.offsetLeft + c.offsetWidth / 2 - mid); if (d < best) { best = d; k = +c.dataset.k; } });
      $$('.fam-chip', chips).forEach(b => { const on = +b.dataset.k === k; b.setAttribute('aria-pressed', on); if (on && b.scrollIntoViewIfNeeded) b.scrollIntoViewIfNeeded(false); });
    });
  }, { passive: true });
  // arrastre con el mouse (en el celu es scroll nativo)
  let ar = null;
  track.addEventListener('pointerdown', e => {
    if (e.pointerType !== 'mouse' || matchMedia('(min-width:900px)').matches || e.target.closest('button,a')) return;
    ar = { x: e.clientX, l: track.scrollLeft, mov: 0 }; track.setPointerCapture(e.pointerId); track.classList.add('arrastrando');
  });
  track.addEventListener('pointermove', e => { if (!ar) return; const dx = e.clientX - ar.x; ar.mov = Math.max(ar.mov, Math.abs(dx)); track.scrollLeft = ar.l - dx; });
  const fin = () => {
    if (!ar) return; ar = null; track.classList.remove('arrastrando');
    const mid = track.scrollLeft + track.clientWidth / 2; let best = null, bd = 1e9;
    $$('.fam', track).forEach(c => { const d = Math.abs(c.offsetLeft + c.offsetWidth / 2 - mid); if (d < bd) { bd = d; best = c; } });
    if (best) track.scrollTo({ left: best.offsetLeft - (track.clientWidth - best.offsetWidth) / 2, behavior: 'smooth' });
  };
  track.addEventListener('pointerup', fin); track.addEventListener('pointercancel', fin);
  track.addEventListener('dragstart', e => e.preventDefault());
}

/* ---------- plato del día (lo carga el dueño en el panel) ---------- */
function hoy(prods) {
  const p = prods.find(x => x.id === 'plato-del-dia'); if (!p) return;
  const nombre = p.nombre.replace(/ de parmesano y ajo/i, '').replace(/ con puré de papa$/i, ' con puré');
  const h2 = $('[data-pizarra]');
  if (h2.dataset.txt !== nombre) { h2.dataset.txt = nombre; pizarra(h2, nombre); }
  const pr = $('[data-pizarra-precio]'); const ptxt = pesos(p.precio);
  if (pr.dataset.txt !== ptxt) { pr.dataset.txt = ptxt; pizarra(pr, ptxt); }
  $('[data-hoy-desc]').textContent = p.descripcion || '';
  const off = p.disponible === false, bt = $('[data-sumar-hoy]');
  $('#hoy').classList.toggle('agotado', off); bt.disabled = off;
  bt.innerHTML = off ? '<span class="n">02</span>Hoy se agotó' : '<span class="n">02</span>Sumá el plato del día';
  $('[data-hoy-corto]').textContent = nombre.split(' ').slice(0, 3).join(' ');
  $('[data-hoy-precio]').textContent = ptxt;
  if (p.foto) { const src = p.foto.replace(/-(240|480|800)\.webp$/, ''); if (/plato-del-dia/.test(src)) { /* foto de la demo */ } else { $('[data-hoy-foto]').src = p.foto; $('[data-hoy-foto-grande]').removeAttribute('srcset'); $('[data-hoy-foto-grande]').src = p.foto; } }
}

/* ---------- popup de fiestas ---------- */
let scrollY0 = 0;
function bloquear(on) {
  if (on) { scrollY0 = scrollY; document.body.style.position = 'fixed'; document.body.style.top = `-${scrollY0}px`; document.body.style.width = '100%'; html.classList.add('pop-abierto'); }
  else { document.body.style.position = ''; document.body.style.top = ''; document.body.style.width = ''; html.classList.remove('pop-abierto'); html.style.scrollBehavior = 'auto'; scrollTo(0, scrollY0); html.style.scrollBehavior = ''; }
}
function fiestas(prods) {
  const ul = $('[data-fiestas-lista]'); if (!ul) return;
  ul.innerHTML = prods.filter(p => p.categoria === 'fiestas').map(p => `<li><img src="${p.foto ? p.foto.replace('-480', '-240') : 'img/cuarto-muslo-240.webp'}" alt="" width="64" height="64" loading="lazy"><div><b>${p.nombre}</b>${p.descripcion ? `<small>${p.descripcion}</small>` : ''}<em>${pesos(p.precio)}</em></div><div data-kit-qty="${p.id}"></div></li>`).join('');
  KIT?.carrito?.sync(ul);
}
function popFiestas() {
  const pop = $('#pop-fiestas'); let antes = null;
  const abrir = () => { antes = document.activeElement; pop.classList.add('abierto'); pop.setAttribute('aria-hidden', 'false'); bloquear(true); $('.pop__x', pop).focus({ preventScroll: true }); };
  const cerrar = () => { if (!pop.classList.contains('abierto')) return; pop.classList.remove('abierto'); pop.setAttribute('aria-hidden', 'true'); bloquear(false); antes?.focus?.({ preventScroll: true }); };
  $('[data-abrir-fiestas]').addEventListener('click', abrir);
  $('[data-cerrar-pop]', pop).addEventListener('click', cerrar);
  pop.addEventListener('click', e => { if (e.target === pop) cerrar(); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') cerrar(); });
  $('[data-ir-pedido]', pop).addEventListener('click', () => { cerrar(); setTimeout(() => KIT?.carrito?.abrir(), 120); });
}

/* ---------- navegación ---------- */
function navegacion() {
  const hero = $('#inicio'), app = $('.appbar'), ind = $('.indice');
  new IntersectionObserver(([e]) => {
    const enHero = e.intersectionRatio > .35;
    html.classList.toggle('en-hero', enHero); app.classList.toggle('ver', !enHero); ind.classList.toggle('ver', !enHero);
  }, { threshold: [0, .35, .6] }).observe(hero);
  const secs = $$('main section[id]');
  const obs = new IntersectionObserver(es => {
    es.forEach(e => { if (e.isIntersecting) $$('[data-sec]').forEach(a => a.classList.toggle('activo', a.dataset.sec === e.target.id)); });
  }, { rootMargin: '-45% 0px -50% 0px' });
  secs.forEach(s => obs.observe(s));
}
function contarPedido() {
  const b = $('.appbar__n'); if (!b || !KIT?.carrito) return;
  const n = KIT.carrito.calc().items.reduce((s, i) => s + i.cant, 0);
  b.hidden = !n; b.textContent = n;
}

/* ---------- entradas al hacer scroll ---------- */
function entradas() {
  const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('visto'); io.unobserve(e.target); } }), { threshold: .18 });
  $$('.rv').forEach(el => io.observe(el));
}

